package cryptoutil

import "math/big"

// The other finite-field groups IKEv1 peers propose. iKuai's L2TP client (and
// strongSwan's IKEv1 default) offers only MODP-3072; older ones MODP-1024.
// The primes are RFC 2409 section 6.2 (group 2) and RFC 3526 sections 4-5
// (groups 15, 16); the generator is 2. (hy2scale P8)

// NewMODP1024 returns the 1024-bit MODP group (RFC 2409, IKE group 2).
func NewMODP1024() DHGroup {
	return &modpGroup{prime: modp1024Prime, g: big.NewInt(2), size: 128}
}

// NewMODP3072 returns the 3072-bit MODP group (RFC 3526, IKE group 15).
func NewMODP3072() DHGroup {
	return &modpGroup{prime: modp3072Prime, g: big.NewInt(2), size: 384}
}

// NewMODP4096 returns the 4096-bit MODP group (RFC 3526, IKE group 16).
func NewMODP4096() DHGroup {
	return &modpGroup{prime: modp4096Prime, g: big.NewInt(2), size: 512}
}

